def __init__(self, toml_offset):
    if toml_offset == "Z":
        self._raw_offset = "+00:00"
    else:
        self._raw_offset = toml_offset
    self._sign = -1 if self._raw_offset[0] == '-' else 1
    self._hours = int(self._raw_offset[1:3])
    self._minutes = int(self._raw_offset[4:6])

